import copy
from collections import defaultdict
from typing import Union

from taf.config.testline.info import info
from taf.hw.rf_diagnostic_card.dispatcher.rmods.setups import RmodsConnectionsSetups
from taf.config.testline.info.exceptions import UserNotDefinedForSWLine, RUNotSupported
from taf.internal.robot_typecasts import to_boolean

from taf.rfrl.csv4all.resources.node.ru_manager.ru_blackbox import RuBlackbox
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger

ALL_RMODS = "All Rmods"

class RuConfiguration:
    def __init__(self, rmod_setup: dict = None, serial_number: str = None, radio_type: str = None, rmod_ip: str = None,
                 preserve_flags: bool = True, commands_after_connect: set = None, fh_interface: str = "CPRI",
                 slave_bts: bool = False, flags_to_add: defaultdict = None, restore_flags: bool = True,
                 verify_blackbox: dict = None):
        self.radio_type = radio_type
        self.serial_number = serial_number
        self._family = None
        self._rmod_families = RmodsConnectionsSetups()
        self._username = None
        self._password = None
        self._connected_rmod = None
        self._preserve_flags = preserve_flags
        self._rmod_setup = rmod_setup
        self._commands_after_connect = commands_after_connect
        self._flags_to_add = flags_to_add
        self.fh_interface = fh_interface
        self.ip_address = rmod_ip
        self.slave_bts = slave_bts
        self._restore_flags = restore_flags
        self.supported = True
        self.verify_blackbox = verify_blackbox
        self.blackbox_content = ""
        self.blackbox = RuBlackbox(**verify_blackbox) if verify_blackbox else None
        test_logger(self, "DEBUG")

    def __repr__(self):
        return (
            "\nRuConfiguration object with following parameters:\n"
            f"serial_number: {self.serial_number}\n"
            f"ip_address: {self.ip_address}\n"
            f"radio_type: {self.radio_type}\n"
            f"radio_family: {self.radio_family}\n"
            f"username: {self.username}\n"
            f"password: {self.password}\n"
            f"preserve_flags: {self._preserve_flags}\n"
            f"slave_bts: {self.slave_bts}\n"
            f"flags_to_add: {self._flags_to_add}\n"
            f"commands_after_connect: {self._commands_after_connect}\n"
            f"restore_flags: {self.restore_flags}\n"
            f"verify_blackbox: {self.verify_blackbox}\n"
            f"fh_interface: {self.fh_interface}\n"
        )

    @property
    def radio_family(self) -> str:
        if self._family is None:
            for rmod_setup in self._rmod_families.setups:
                if self.radio_type in rmod_setup.product_names:
                    self._family = rmod_setup.program
                    self._connected_rmod = {self._family: rmod_setup}
                    break
                else:
                    self._family = "Unknown"
                    self._connected_rmod = {
                        self._family: [
                            unknown for unknown in self._rmod_families.setups if unknown.program == self._family
                        ][0]
                    }
        return self._family

    @property
    def preserve_flags(self) -> bool:
        return self._preserve_flags

    @preserve_flags.setter
    def preserve_flags(self, preserve_flags: Union[str, bool]) -> None:
        if isinstance(preserve_flags, str):
            preserve_flags = to_boolean(preserve_flags)
        self._preserve_flags = preserve_flags

    @property
    def restore_flags(self) -> bool:
        return self._restore_flags

    @restore_flags.setter
    def restore_flags(self, restore_flags: Union[str, bool]) -> None:
        if isinstance(restore_flags, str):
            restore_flags = to_boolean(restore_flags)
        self._restore_flags = restore_flags

    @property
    def commands_after_connect(self) -> set:
        return self._commands_after_connect

    @commands_after_connect.setter
    def commands_after_connect(self, commands_after_connect: list) -> None:
        if isinstance(commands_after_connect, str):
            commands_after_connect = [commands_after_connect]
        commands_after_connect = set(commands_after_connect)
        if not self._commands_after_connect or not commands_after_connect:
            self._commands_after_connect = commands_after_connect
        else:
            self._commands_after_connect.update(commands_after_connect)

    @property
    def flags_to_add(self) -> defaultdict:
        return self._flags_to_add

    @flags_to_add.setter
    def flags_to_add(self, flags_to_add: dict) -> None:
        if not self._flags_to_add or not flags_to_add:
            self._flags_to_add = flags_to_add
        else:
            self._flags_to_add.update(flags_to_add)

    @property
    def username(self) -> str:
        if self._username is None:
            self._username, self._password = self._get_ru_user_and_password()
        return self._username

    @property
    def password(self) -> str:
        if self._password is None:
            self._username, self._password = self._get_ru_user_and_password()
        return self._password

    def _get_ru_user_and_password(self) -> tuple:
        tl_info = info()
        legacy_root_credentials = "root", ""
        try:
            sw_line = tl_info.get_ru_sw_line(radio_type=self.radio_type, fh_interface=self.fh_interface)
            return "serviceuser", tl_info.get_ru_password(by_sw_line=sw_line, fh_interface=self.fh_interface)
        except RUNotSupported as e:
            test_logger(e, "ERROR")
            self.supported = False
            return "", ""
        except UserNotDefinedForSWLine:
            return legacy_root_credentials

    def update_attributes(self, **kwargs) -> None:
        for attr, value in kwargs.items():
            setattr(self, attr, value)
